<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/config/database.php';
require_moderator();
$tabs = is_admin()
    ? ['overview', 'articles', 'users', 'search', 'bots', 'imports', 'automation', 'settings', 'media', 'reports', 'activity']
    : ['overview', 'articles', 'search', 'imports', 'automation', 'media', 'reports', 'activity'];
$tab = in_array($_GET['tab'] ?? 'overview', $tabs, true) ? $_GET['tab'] : 'overview';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $action = (string) ($_POST['action'] ?? '');
    if ($action === 'article_update') {
        $id = (int) ($_POST['article_id'] ?? 0);
        $status = in_array($_POST['status'] ?? '', ['published', 'pending', 'draft', 'archived'], true) ? $_POST['status'] : 'pending';
        $featured = !empty($_POST['is_featured']) ? 1 : 0;
        $articleStmt = $pdo->prepare('SELECT slug, status FROM articles WHERE id = ?'); $articleStmt->execute([$id]); $before = $articleStmt->fetch();
        if ($before && active_article_protection($pdo, $id) && !is_admin()) {
            flash('error', 'Only an administrator can moderate this protected article.');
            redirect('/admin?tab=articles');
        }
        $pdo->prepare('UPDATE articles SET status = ?, is_featured = ?, published_at = CASE WHEN ? = \'published\' THEN COALESCE(published_at, UTC_TIMESTAMP()) ELSE published_at END WHERE id = ?')->execute([$status, $featured, $status, $id]);
        log_activity($pdo, 'admin.article_updated', 'article', $id, ['status' => $status, 'featured' => $featured]);
        if ($before && $status === 'published' && $before['status'] !== 'published') notify_indexnow([site_url('/wiki/' . $before['slug']), site_url('/'), site_url('/feed.xml')]);
        flash('success', 'Article moderation settings updated.');
    } elseif ($action === 'article_protect') {
        if (!is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
        $id = (int) ($_POST['article_id'] ?? 0);
        $reason = mb_substr(trim((string) ($_POST['reason'] ?? '')), 0, 500);
        $days = max(0, min(3650, (int) ($_POST['expiry_days'] ?? 0)));
        $articleExistsStmt = $pdo->prepare('SELECT 1 FROM articles WHERE id = ?'); $articleExistsStmt->execute([$id]);
        if (!$articleExistsStmt->fetchColumn() || mb_strlen($reason) < 3) {
            flash('error', 'Choose an article and enter a protection reason.');
        } else {
            $expires = $days > 0 ? gmdate('Y-m-d H:i:s', time() + $days * 86400) : null;
            $pdo->prepare("INSERT INTO article_protections (article_id, protection_level, reason, protected_by, expires_at) VALUES (?, 'administrator', ?, ?, ?) ON DUPLICATE KEY UPDATE reason = VALUES(reason), protected_by = VALUES(protected_by), expires_at = VALUES(expires_at), updated_at = UTC_TIMESTAMP()")->execute([$id, $reason, current_user()['id'], $expires]);
            $pdo->prepare("INSERT INTO protection_log (article_id, administrator_id, action, reason, expires_at) VALUES (?, ?, 'protect', ?, ?)")->execute([$id, current_user()['id'], $reason, $expires]);
            log_activity($pdo, 'admin.article_protected', 'article', $id, ['reason' => $reason, 'expires_at' => $expires]);
            flash('success', 'Article protection is active; only administrators can edit or restore it.');
        }
    } elseif ($action === 'article_unprotect') {
        if (!is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
        $id = (int) ($_POST['article_id'] ?? 0);
        $reasonStmt = $pdo->prepare('SELECT reason FROM article_protections WHERE article_id = ?'); $reasonStmt->execute([$id]); $oldReason = $reasonStmt->fetchColumn();
        if ($oldReason === false) {
            flash('warning', 'That article does not have an active protection record.');
        } else {
            $pdo->prepare('DELETE FROM article_protections WHERE article_id = ?')->execute([$id]);
            $pdo->prepare("INSERT INTO protection_log (article_id, administrator_id, action, reason) VALUES (?, ?, 'unprotect', ?)")->execute([$id, current_user()['id'], $oldReason ?: 'Protection removed']);
            log_activity($pdo, 'admin.article_unprotected', 'article', $id);
            flash('success', 'Article protection removed.');
        }
    } elseif ($action === 'bot_job_queue') {
        if (!is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
        require_once APP_ROOT . '/includes/BotService.php';
        try {
            $jobId = (new BotService($pdo))->queue((int) ($_POST['bot_id'] ?? 1), (int) current_user()['id'], $_POST);
            $pdo->prepare("UPDATE scheduled_tasks SET next_run_at = UTC_TIMESTAMP(), locked_at = NULL, status = 'idle' WHERE task_name = 'bot_article_queue'")->execute();
            flash('success', 'Bot job #' . $jobId . ' queued. It will run after this request or the next visit.');
        } catch (BotJobException $exception) {
            flash('error', $exception->getMessage());
        }
    } elseif ($action === 'bot_job_retry') {
        if (!is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
        $jobId = (int) ($_POST['job_id'] ?? 0);
        $pdo->prepare("UPDATE bot_jobs SET status = 'queued', scheduled_for = UTC_TIMESTAMP(), error_message = NULL, started_at = NULL, completed_at = NULL WHERE id = ? AND status IN ('failed','cancelled')")->execute([$jobId]);
        $pdo->prepare("UPDATE scheduled_tasks SET next_run_at = UTC_TIMESTAMP(), locked_at = NULL, status = 'idle' WHERE task_name = 'bot_article_queue'")->execute();
        log_activity($pdo, 'bot.job_retried', 'bot_job', $jobId);
        flash('success', 'Bot job returned to the queue.');
    } elseif ($action === 'bot_job_cancel') {
        if (!is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
        $jobId = (int) ($_POST['job_id'] ?? 0);
        $pdo->prepare("UPDATE bot_jobs SET status = 'cancelled', completed_at = UTC_TIMESTAMP() WHERE id = ? AND status = 'queued'")->execute([$jobId]);
        log_activity($pdo, 'bot.job_cancelled', 'bot_job', $jobId);
        flash('success', 'Queued bot job cancelled.');
    } elseif ($action === 'bot_toggle') {
        if (!is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
        $botId = (int) ($_POST['bot_id'] ?? 0);
        $status = ($_POST['status'] ?? '') === 'active' ? 'active' : 'paused';
        $pdo->prepare('UPDATE bots SET status = ? WHERE id = ?')->execute([$status, $botId]);
        log_activity($pdo, 'bot.status_updated', 'bot', $botId, ['status' => $status]);
        flash('success', 'Bot status updated.');
    } elseif ($action === 'bot_update') {
        if (!is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
        $botId = (int) ($_POST['bot_id'] ?? 0);
        $dailyLimit = max(1, min(100, (int) ($_POST['daily_limit'] ?? 25)));
        $description = mb_substr(trim((string) ($_POST['description'] ?? '')), 0, 500);
        $pdo->prepare('UPDATE bots SET daily_limit = ?, description = ? WHERE id = ?')->execute([$dailyLimit, $description ?: null, $botId]);
        log_activity($pdo, 'bot.configuration_updated', 'bot', $botId, ['daily_limit' => $dailyLimit]);
        flash('success', 'Bot safety controls updated.');
    } elseif ($action === 'user_update') {
        if (!is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
        $id = (int) ($_POST['user_id'] ?? 0);
        $role = in_array($_POST['role'] ?? '', ['editor', 'moderator', 'administrator'], true) ? $_POST['role'] : 'editor';
        $status = in_array($_POST['status'] ?? '', ['active', 'blocked'], true) ? $_POST['status'] : 'active';
        if ($id === (int) current_user()['id'] && ($role !== 'administrator' || $status !== 'active')) {
            flash('error', 'You cannot demote or block your own active administrator account.');
        } else {
            $pdo->prepare('UPDATE users SET role = ?, status = ? WHERE id = ?')->execute([$role, $status, $id]);
            log_activity($pdo, 'admin.user_updated', 'user', $id, ['role' => $role, 'status' => $status]);
            flash('success', 'User permissions updated.');
        }
    } elseif ($action === 'search_synonym_add') {
        $term = mb_substr(normalize_search_query((string) ($_POST['term'] ?? '')), 0, 120);
        $synonym = mb_substr(normalize_search_query((string) ($_POST['synonym'] ?? '')), 0, 120);
        $weight = max(0.1, min(2.0, (float) ($_POST['weight'] ?? 0.75)));
        if ($term === '' || $synonym === '' || $term === $synonym) {
            flash('error', 'Enter two different search terms.');
        } else {
            $pdo->prepare('INSERT INTO search_synonyms (term, synonym, weight, is_active) VALUES (?, ?, ?, 1) ON DUPLICATE KEY UPDATE weight = VALUES(weight), is_active = 1')->execute([$term, $synonym, $weight]);
            log_activity($pdo, 'admin.search_synonym_saved', 'search');
            flash('success', 'Search synonym saved.');
        }
    } elseif ($action === 'search_synonym_delete') {
        $pdo->prepare('DELETE FROM search_synonyms WHERE id = ?')->execute([(int) ($_POST['synonym_id'] ?? 0)]);
        log_activity($pdo, 'admin.search_synonym_deleted', 'search');
        flash('success', 'Search synonym removed.');
    } elseif ($action === 'search_reindex') {
        $pdo->exec("INSERT INTO search_documents (article_id, title, normalized_title, body, excerpt, language, quality_score, popularity_score, updated_at)
            SELECT id, title, LOWER(title), content, excerpt, 'bn', LEAST(100, LEAST(30, CHAR_LENGTH(content) / 500) + LEAST(50, (CHAR_LENGTH(content) - CHAR_LENGTH(REPLACE(content, '<ref', ''))) / 4 * 10)), (LOG10(views + 10) * 8 + likes * 4 + edit_count), updated_at FROM articles
            ON DUPLICATE KEY UPDATE title = VALUES(title), normalized_title = VALUES(normalized_title), body = VALUES(body), excerpt = VALUES(excerpt), quality_score = VALUES(quality_score), popularity_score = VALUES(popularity_score), updated_at = VALUES(updated_at)");
        log_activity($pdo, 'admin.search_reindexed', 'search');
        flash('success', 'The search index was rebuilt.');
    } elseif ($action === 'task_run_now') {
        $taskName = (string) ($_POST['task_name'] ?? '');
        if (in_array($taskName, ['indexnow_full_refresh', 'bot_article_queue'], true)) {
            if ($taskName === 'bot_article_queue' && !is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
            $pdo->prepare("UPDATE scheduled_tasks SET next_run_at = UTC_TIMESTAMP(), locked_at = NULL, status = 'idle' WHERE task_name = ?")->execute([$taskName]);
            log_activity($pdo, 'admin.task_scheduled', 'scheduled_task', null, ['task' => $taskName]);
            flash('success', ($taskName === 'bot_article_queue' ? 'Bot queue' : 'IndexNow submission') . ' is due and will run as this request closes.');
        }
    } elseif ($action === 'settings_update') {
        if (!is_admin()) { http_response_code(403); exit('Administrator access is required.'); }
        $settings = [
            'site_tagline' => mb_substr(trim((string) ($_POST['site_tagline'] ?? '')), 0, 300),
            'homepage_notice' => mb_substr(trim((string) ($_POST['homepage_notice'] ?? '')), 0, 500),
            'default_meta_description' => mb_substr(trim((string) ($_POST['default_meta_description'] ?? '')), 0, 320),
            'allow_registration' => !empty($_POST['allow_registration']) ? '1' : '0',
            'require_review' => !empty($_POST['require_review']) ? '1' : '0',
            'remote_import_enabled' => !empty($_POST['remote_import_enabled']) ? '1' : '0',
            'bot_scheduler_enabled' => !empty($_POST['bot_scheduler_enabled']) ? '1' : '0',
            'bot_default_mode' => in_array($_POST['bot_default_mode'] ?? '', ['draft', 'pending', 'published'], true) ? (string) $_POST['bot_default_mode'] : 'pending',
            'indexnow_interval_minutes' => (string) max(10, min(1440, (int) ($_POST['indexnow_interval_minutes'] ?? 50))),
        ];
        foreach ($settings as $key => $value) save_setting($pdo, $key, $value, !in_array($key, ['bot_scheduler_enabled', 'bot_default_mode'], true));
        log_activity($pdo, 'admin.settings_updated', 'settings'); flash('success', 'Site settings saved.');
    } elseif ($action === 'report_update') {
        $id = (int) ($_POST['report_id'] ?? 0); $status = in_array($_POST['status'] ?? '', ['open', 'reviewing', 'resolved', 'dismissed'], true) ? $_POST['status'] : 'open';
        $pdo->prepare('UPDATE reports SET status = ? WHERE id = ?')->execute([$status, $id]); log_activity($pdo, 'admin.report_updated', 'report', $id, ['status' => $status]); flash('success', 'Report status updated.');
    }
    redirect('/admin?tab=' . rawurlencode($tab));
}

$page = max(1, (int) ($_GET['page'] ?? 1)); $limit = 50; $offset = ($page - 1) * $limit;
$stats = $pdo->query("SELECT
 (SELECT COUNT(*) FROM articles WHERE status = 'published') published,
 (SELECT COUNT(*) FROM articles WHERE status = 'pending') pending,
 (SELECT COUNT(*) FROM users) users,
 (SELECT COUNT(*) FROM revisions) revisions,
 (SELECT COALESCE(SUM(views),0) FROM articles) views,
 (SELECT COUNT(*) FROM images) images,
 (SELECT COUNT(*) FROM reports WHERE status = 'open') reports,
 (SELECT COUNT(*) FROM article_protections WHERE expires_at IS NULL OR expires_at > UTC_TIMESTAMP()) protected,
 (SELECT COUNT(*) FROM bot_jobs WHERE status = 'queued') bot_queued")->fetch();
$recentActivity = $topArticles = $articles = $users = $media = $reports = $activity = $topQueries = $zeroQueries = $synonyms = $imports = $scheduledTasks = $indexingRuns = $bots = $botJobs = $botRuns = [];
if ($tab === 'overview') {
    $recentActivity = $pdo->query('SELECT l.*, u.username FROM activity_log l LEFT JOIN users u ON u.id = l.user_id ORDER BY l.id DESC LIMIT 12')->fetchAll();
    $topArticles = $pdo->query("SELECT title, slug, views, likes, edit_count FROM articles WHERE status = 'published' ORDER BY views DESC LIMIT 8")->fetchAll();
} elseif ($tab === 'articles') {
    $articles = $pdo->query("SELECT a.id, a.title, a.slug, a.status, a.is_featured, a.views, a.updated_at, u.username, p.reason AS protection_reason, p.expires_at AS protection_expires FROM articles a LEFT JOIN users u ON u.id = a.author_id LEFT JOIN article_protections p ON p.article_id = a.id AND (p.expires_at IS NULL OR p.expires_at > UTC_TIMESTAMP()) ORDER BY CASE a.status WHEN 'pending' THEN 0 WHEN 'draft' THEN 1 ELSE 2 END, a.updated_at DESC LIMIT {$limit} OFFSET {$offset}")->fetchAll();
    $protectionLog = $pdo->query("SELECT pl.*, a.title, a.slug, u.username AS administrator_name FROM protection_log pl JOIN articles a ON a.id = pl.article_id LEFT JOIN users u ON u.id = pl.administrator_id ORDER BY pl.id DESC LIMIT 20")->fetchAll();
} elseif ($tab === 'users') {
    $users = $pdo->query("SELECT u.id, u.username, u.email, u.role, u.status, u.created_at, u.last_login_at, COUNT(r.id) edits FROM users u LEFT JOIN revisions r ON r.user_id = u.id GROUP BY u.id, u.username, u.email, u.role, u.status, u.created_at, u.last_login_at ORDER BY u.created_at DESC LIMIT {$limit} OFFSET {$offset}")->fetchAll();
} elseif ($tab === 'search') {
    $topQueries = $pdo->query("SELECT normalized_query, COUNT(*) searches, ROUND(AVG(result_count)) average_results, MAX(created_at) last_searched FROM search_queries WHERE created_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 30 DAY) GROUP BY normalized_query ORDER BY searches DESC, last_searched DESC LIMIT 25")->fetchAll();
    $zeroQueries = $pdo->query("SELECT normalized_query, COUNT(*) searches, MAX(created_at) last_searched FROM search_queries WHERE result_count = 0 AND created_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 30 DAY) GROUP BY normalized_query ORDER BY searches DESC, last_searched DESC LIMIT 20")->fetchAll();
    $synonyms = $pdo->query('SELECT * FROM search_synonyms ORDER BY term, weight DESC')->fetchAll();
} elseif ($tab === 'bots') {
    $bots = $pdo->query('SELECT * FROM bots ORDER BY id')->fetchAll();
    $botJobs = $pdo->query("SELECT j.*, b.name AS bot_name, u.username, a.slug AS article_slug FROM bot_jobs j JOIN bots b ON b.id = j.bot_id LEFT JOIN users u ON u.id = j.requested_by LEFT JOIN articles a ON a.id = j.article_id ORDER BY j.id DESC LIMIT {$limit} OFFSET {$offset}")->fetchAll();
    $botRuns = $pdo->query('SELECT r.*, b.name AS bot_name FROM bot_runs r JOIN bots b ON b.id = r.bot_id ORDER BY r.id DESC LIMIT 20')->fetchAll();
} elseif ($tab === 'imports') {
    $imports = $pdo->query("SELECT ri.*, u.username, a.title AS article_title, a.slug AS article_slug FROM remote_imports ri LEFT JOIN users u ON u.id = ri.user_id LEFT JOIN articles a ON a.id = ri.article_id ORDER BY ri.id DESC LIMIT {$limit} OFFSET {$offset}")->fetchAll();
} elseif ($tab === 'automation') {
    $scheduledTasks = $pdo->query('SELECT * FROM scheduled_tasks ORDER BY task_name')->fetchAll();
    $indexingRuns = $pdo->query('SELECT * FROM indexing_submissions ORDER BY id DESC LIMIT 50')->fetchAll();
} elseif ($tab === 'media') {
    $media = $pdo->query("SELECT i.*, u.username, ms.source_url, ms.source_page_url, ms.license_name, ms.attribution FROM images i LEFT JOIN users u ON u.id = i.user_id LEFT JOIN media_sources ms ON ms.id = (SELECT MAX(ms2.id) FROM media_sources ms2 WHERE ms2.image_id = i.id) ORDER BY i.id DESC LIMIT {$limit} OFFSET {$offset}")->fetchAll();
} elseif ($tab === 'reports') {
    $reports = $pdo->query("SELECT r.*, a.title, a.slug, u.username FROM reports r LEFT JOIN articles a ON a.id = r.article_id LEFT JOIN users u ON u.id = r.user_id ORDER BY CASE r.status WHEN 'open' THEN 0 WHEN 'reviewing' THEN 1 ELSE 2 END, r.id DESC LIMIT {$limit} OFFSET {$offset}")->fetchAll();
} elseif ($tab === 'activity') {
    $activity = $pdo->query("SELECT l.*, u.username FROM activity_log l LEFT JOIN users u ON u.id = l.user_id ORDER BY l.id DESC LIMIT {$limit} OFFSET {$offset}")->fetchAll();
}
$adminNav = ['overview' => 'Overview', 'articles' => 'Articles', 'users' => 'Users & roles', 'search' => 'Search intelligence', 'bots' => 'Automation bots', 'imports' => 'Encyclopedia imports', 'automation' => 'SEO automation', 'settings' => 'Site settings', 'media' => 'Media library', 'reports' => 'Reports', 'activity' => 'Activity log'];
if (!is_admin()) { unset($adminNav['users'], $adminNav['bots'], $adminNav['settings']); }
$page_title = (is_admin() ? 'Administration' : 'Moderation') . ' — ' . SITE_NAME; $page_robots = 'noindex,nofollow';
require APP_ROOT . '/includes/header.php';
?>
<main id="main-content" class="admin-layout">
<aside class="admin-sidebar"><strong><?= is_admin() ? 'Control center' : 'Moderation' ?></strong><nav><?php foreach ($adminNav as $key => $label): ?><a class="<?= $tab === $key ? 'active' : '' ?>" href="/admin?tab=<?= e($key) ?>"><?= e($label) ?><?= $key === 'reports' && $stats['reports'] ? ' (' . (int) $stats['reports'] . ')' : '' ?></a><?php endforeach; ?></nav></aside>
<section class="admin-main">
<h1><?= e(ucwords(str_replace('_', ' ', $tab))) ?></h1>
<?php if ($tab === 'overview'): ?>
<div class="admin-grid"><div class="stat-card"><strong><?= format_number($stats['published']) ?></strong><span>Published articles</span></div><div class="stat-card"><strong><?= format_number($stats['views']) ?></strong><span>Total views</span></div><div class="stat-card"><strong><?= format_number($stats['users']) ?></strong><span>Community members</span></div><div class="stat-card"><strong><?= format_number($stats['pending']) ?></strong><span>Awaiting review</span></div><div class="stat-card"><strong><?= format_number($stats['protected']) ?></strong><span>Protected pages</span></div><div class="stat-card"><strong><?= format_number($stats['bot_queued']) ?></strong><span>Queued bot jobs</span></div></div>
<div class="admin-two-column"><section class="panel"><div class="panel-header"><h2>Recent system activity</h2><a href="?tab=activity">View log</a></div><div class="table-responsive"><table class="list-table"><thead><tr><th>Action</th><th>User</th><th>When</th></tr></thead><tbody><?php foreach ($recentActivity as $item): ?><tr><td><?= e(str_replace('.', ' · ', $item['action'])) ?></td><td><?= e($item['username'] ?: 'System') ?></td><td><?= e(time_ago($item['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section><aside class="panel"><div class="panel-header"><h2>System health</h2></div><div class="panel-body health-list"><div class="health-item"><span>Database schema</span><span class="health-good">v<?= e(setting($pdo, 'schema_version', '?')) ?></span></div><div class="health-item"><span>Secure HTTPS URL</span><span class="<?= str_starts_with(SITE_URL, 'https://') ? 'health-good' : 'health-warn' ?>"><?= str_starts_with(SITE_URL, 'https://') ? 'Ready' : 'Check URL' ?></span></div><div class="health-item"><span>ImgBB uploads</span><span class="<?= IMGBB_API_KEY !== '' ? 'health-good' : 'health-warn' ?>"><?= IMGBB_API_KEY !== '' ? 'Configured' : 'Needs key' ?></span></div><div class="health-item"><span>IndexNow</span><span class="<?= INDEXNOW_KEY !== '' ? 'health-good' : 'health-warn' ?>"><?= INDEXNOW_KEY !== '' ? 'Configured' : 'Optional' ?></span></div><div class="health-item"><span>PHP runtime</span><strong><?= e(PHP_VERSION) ?></strong></div></div></aside></div>
<section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Most-read articles</h2></div><div class="table-responsive"><table class="list-table"><thead><tr><th>Article</th><th>Views</th><th>Likes</th><th>Edits</th></tr></thead><tbody><?php foreach ($topArticles as $item): ?><tr><td><a href="/wiki/<?= e($item['slug']) ?>"><?= e($item['title']) ?></a></td><td><?= format_number($item['views']) ?></td><td><?= format_number($item['likes']) ?></td><td><?= format_number($item['edit_count']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php elseif ($tab === 'articles'): ?>
<section class="panel"><div class="panel-header"><h2>Article moderation</h2><span class="badge"><?= format_number(count($articles)) ?> shown</span></div><div class="table-responsive"><table class="list-table"><thead><tr><th>Article</th><th>Author</th><th>Views</th><th>Moderation</th></tr></thead><tbody><?php foreach ($articles as $item): ?><tr><td><a href="/wiki/<?= e($item['slug']) ?>"><strong><?= e($item['title']) ?></strong></a><br><small><?= e(time_ago($item['updated_at'])) ?></small></td><td><?= e($item['username'] ?: 'Unknown') ?></td><td><?= format_number($item['views']) ?></td><td><?php if (!$item['protection_reason'] || is_admin()): ?><form class="inline-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="article_update"><input type="hidden" name="article_id" value="<?= (int) $item['id'] ?>"><select name="status" aria-label="Status"><option value="published" <?= $item['status'] === 'published' ? 'selected' : '' ?>>Published</option><option value="pending" <?= $item['status'] === 'pending' ? 'selected' : '' ?>>Pending</option><option value="draft" <?= $item['status'] === 'draft' ? 'selected' : '' ?>>Draft</option><option value="archived" <?= $item['status'] === 'archived' ? 'selected' : '' ?>>Archived</option></select><label class="checkbox"><input type="checkbox" name="is_featured" value="1" <?= $item['is_featured'] ? 'checked' : '' ?>> Featured</label><button class="button" type="submit">Save</button></form><?php else: ?><span class="form-help">Administrator-only moderation</span><?php endif; ?><?php if ($item['protection_reason']): ?><div class="protection-admin"><span class="badge badge-blocked">🔒 <?= e($item['protection_reason']) ?></span><?php if (is_admin()): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="article_unprotect"><input type="hidden" name="article_id" value="<?= (int) $item['id'] ?>"><button class="button button-quiet" type="submit">Remove protection</button></form><?php endif; ?></div><?php elseif (is_admin()): ?><details class="protection-admin"><summary>Protect page</summary><form class="inline-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="article_protect"><input type="hidden" name="article_id" value="<?= (int) $item['id'] ?>"><input name="reason" maxlength="500" required placeholder="Protection reason"><select name="expiry_days" aria-label="Protection duration"><option value="0">Permanent</option><option value="1">1 day</option><option value="7">1 week</option><option value="30">30 days</option><option value="365">1 year</option></select><button class="button" type="submit">Protect</button></form></details><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
