ing' => 'Pending human review', 'published' => 'Publish automatically'] as $value => $label): ?><option value="<?= e($value) ?>" <?= setting($pdo, 'bot_default_mode', 'pending') === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="form-group"><label for="indexnow-interval">IndexNow full refresh interval (minutes)</label><input id="indexnow-interval" type="number" name="indexnow_interval_minutes" min="10" max="1440" value="<?= e(setting($pdo, 'indexnow_interval_minutes', '50')) ?>"><p class="form-help">Runs through normal traffic without cron. Fifty minutes is the recommended configured schedule for this installation.</p></div><button class="button button-primary" type="submit">Save settings</button></form><hr><p class="form-help">Database, ImgBB, site URL, and IndexNow secrets are intentionally managed in <code>config/local.php</code> or environment variables—not in this public admin form.</p></div></section>
